from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
vehicleid_to_type = {}
vehicleid_to_capacity = {}
for rec in capacity_records:
    v_id = int(rec['values']['VehicleID'])
    v_type = rec['values']['VehicleType']
    v_cap = int(rec['values']['Capacity'])
    vehicleid_to_type[v_id] = v_type
    vehicleid_to_capacity[v_id] = v_cap
vehicletype_to_value = {}
for rec in product_records:
    v_type = rec['values']['ProductName']
    v_val = int(rec['values']['Value'])
    vehicletype_to_value[v_type] = v_val
vehicleid_to_value = {}
for (v_id, v_type) in vehicleid_to_type.items():
    if v_type not in vehicletype_to_value:
        raise ValueError(f'Missing value for vehicle type {v_type}')
    vehicleid_to_value[v_id] = vehicletype_to_value[v_type]
vehicle_ids = sorted(vehicleid_to_type.keys())
for v_id in vehicle_ids:
    if v_id not in vehicleid_to_capacity:
        raise ValueError(f'Missing capacity for VehicleID {v_id}')
    if v_id not in vehicleid_to_value:
        raise ValueError(f'Missing value for VehicleID {v_id}')
total_capacity = sum((vehicleid_to_capacity[v_id] for v_id in vehicle_ids))
m = gp.Model('NewCarSalesInNorway')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(vehicle_ids, lb=0, ub=[vehicleid_to_capacity[v_id] for v_id in vehicle_ids], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((vehicleid_to_value[v_id] * x_vars[v_id] for v_id in vehicle_ids)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((x_vars[v_id] for v_id in vehicle_ids)) <= total_capacity, name='total_capacity')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v_id in vehicle_ids:
        print(f'x[{v_id}]: {x_vars[v_id].X}')
else:
    print(f'Solver status: {m.Status}')
